class Solution {
    static const long long CAP = 1000001LL;

    // Calculate C(n, r), capped at CAP.
    long long combination(int n, int r) {
        r = min(r, n - r);

        long long result = 1;

        for (int i = 1; i <= r; ++i) {
            result = result * (n - r + i) / i;

            if (result >= CAP)
                return CAP;
        }

        return result;
    }

    // Count distinct permutations of the remaining
    // characters, capped at CAP.
    long long countWays(const vector<int>& cnt) {
        int remaining = 0;

        for (int x : cnt)
            remaining += x;

        long long ways = 1;

        for (int x : cnt) {
            if (x == 0)
                continue;

            long long choices = combination(remaining, x);

            ways = min(CAP, ways * choices);

            if (ways >= CAP)
                return CAP;

            remaining -= x;
        }

        return ways;
    }

public:
    string smallestPalindrome(string s, int k) {
        vector<int> freq(26, 0);

        for (char c : s)
            ++freq[c - 'a'];

        vector<int> cnt(26, 0);
        string middle = "";

        int halfLength = 0;

        for (int i = 0; i < 26; ++i) {
            cnt[i] = freq[i] / 2;
            halfLength += cnt[i];

            if (freq[i] % 2 == 1)
                middle = string(1, char('a' + i));
        }

        // Not enough distinct palindromes.
        if (countWays(cnt) < k)
            return "";

        string left;
        left.reserve(halfLength);

        for (int pos = 0; pos < halfLength; ++pos) {
            for (int c = 0; c < 26; ++c) {
                if (cnt[c] == 0)
                    continue;

                // Try choosing this character.
                --cnt[c];

                long long ways = countWays(cnt);

                if (ways >= k) {
                    left.push_back(char('a' + c));
                    break;
                }

                // Skip this block of permutations.
                k -= static_cast<int>(ways);
                ++cnt[c];
            }
        }

        string right = left;
        reverse(right.begin(), right.end());

        return left + middle + right;
    }
};
